    absX = abs(x)
    absY = abs(y)
    a = abs(absY - absX)
    # 0인 경우는 좀 다르게 취급된다
    if x == 0:
        if y > 0:
            return y-x
        else:
            return -y+1
    if y == 0:
        if x > 0:
            return 1+x
        else:
            return -x

