    if (x > 0 and y > 0):
        if absX < absY:
            return y-x
        else:
            return 1+(x-y)+1
    if (x < 0 and y > 0):
        if absX < absY:
            return 1+(y+x)
        else:
            return (y-x)
    if (x > 0 and y < 0):
        if absX < absY:
            return -(y+x)+1
        else:
