import sys

sys.setrecursionlimit(10 ** 5 + 10)


def input(): return sys.stdin.readline().strip()


def resolve():
    def main(x, y):

        if 0 <= x < y:
            return y - x
        elif 0 <= y < x:
            return min(y+x+1, -y+x+2)
        elif x <= 0 <= y:
            if abs(x) <= abs(y):
                return min(y-x, y+x+1)
            else:
                return min(y-x, -y-x+1)
        elif y <= 0 <= x:
            if abs(x) <= abs(y):
                return - y - x + 1
            else:
                return y + x + 1
        elif x < y <= 0:
            return y - x
        elif y < x <= 0:
            return min(-y-x+1, -y+x+2)

    x, y = map(int, input().split())

    print(main(x, y))


resolve()

