        elif x <= 0 <= y:
            if (-1) * x <= y:
                return 1 + (y - (-x))
            else:
                return -y - x + 1

        elif 0 <= y <= x:
            return 1 + (-y - (-x)) + 1
        elif y <= x <= 0:
            return main(-x, y) + 1
        elif y <= 0 <= x:
            if (-1) * x <= y:
                return 1 + y + x
            else:
                return -y - x + 1

    x, y = map(int, input().split())

    print(main(x, y))


